export function templateCampaignDetails(templateId: string): Campaign | null {
  return Object.prototype.hasOwnProperty.call(campaigns, templateId) ? campaigns[templateId as CampaignTemplateId] : null;
}

/** Enrich a fresh template copy. IDs, answer mappings and scoring stay intact. */
export function applyTemplateCampaign(form: FormSchemaType, templateId: string): FormSchemaType {
  const campaign = templateCampaignDetails(templateId);
  if (!campaign) return form;
  const next = structuredClone(form), marketing = next.marketing;
  if (!marketing || !next.coverPage) throw Error("Campaign templates require a cover and marketing results.");
  next.coverPage = {
    ...next.coverPage, layout: campaign.coverLayout, title: campaign.title, subtitle: campaign.promise, buttonText: campaign.button,
    sections: [
      { id: "campaign-benefits", type: "benefits", title: "What you will take away", body: "", url: "", label: "", items: [...campaign.benefits] },
      { id: "campaign-context", type: "text", title: campaign.context[0], body: campaign.context[1], url: "", label: "", items: [] },
      { id: "campaign-faq", type: "faq", title: campaign.faq[0], body: campaign.faq[1], url: "", label: "", items: [] },
      { id: "campaign-privacy", type: "faq", title: "Do I need to share my email to see the result?", body: "No. You can skip the optional contact step and see your result. Sharing details is your choice; it does not sign you up for marketing emails.", url: "", label: "", items: [] },
      { id: "campaign-start", type: "start", title: "A useful next step starts with what matters to you.", body: "Choose the answers that fit today. You can take your time.", label: campaign.button, url: "", items: [] },
    ],
  };
  marketing.presentation = { layout: campaign.layout };
  marketing.fallbackTitle = campaign.fallback[0]; marketing.fallbackMessage = campaign.fallback[1];
  const common: ResultSection[] = [
    { id: "campaign-reflection", type: "text", title: campaign.reflection[0], body: campaign.reflection[1], url: "", label: "" },
    { id: "campaign-result-faq", type: "faq", title: campaign.resultFaq[0], body: campaign.resultFaq[1], url: "", label: "" },
  ];
  if (marketing.kind === "scorecard") {
    if (!marketing.scorecard || marketing.scorecard.bands.length !== 3) throw Error("Campaign scorecards require three result bands.");
    if (!campaign.categoryContext || marketing.categories.length !== 3) throw Error("Campaign scorecards require context for three areas.");
    // Descriptions explain the measured area. Band advice/actions retain the original scoring-path guidance.
    marketing.categories.forEach((category, index) => { category.description = campaign.categoryContext![index]; });
    marketing.scorecard.message = "A snapshot of the practices you reported, with a useful next step for each area. Unknown answers remain unscored. This is not an independent audit or certification.";
    marketing.resultSections = marketing.scorecard.bands.map((band, index) => (
      { id: `campaign-${band.id}`, type: "text" as const, title: ["Your first practical check", "Make the useful habits repeatable", "Keep testing what is working"][index], body: campaign.plans[index], url: "", label: "", condition: { type: "score" as const, min: band.min, max: band.max } }
    ));
  } else {
    if (marketing.outcomes.length !== 3) throw Error("Campaign matching templates require three outcomes.");
    marketing.resultSections = marketing.outcomes.map((outcome, index) => {
      // Advice stays short; the result section provides a practical expanded plan.
      return { id: `campaign-${outcome.id}`, type: "text" as const, title: "Try this before making a bigger decision", body: campaign.plans[index], url: "", label: "", condition: { type: "outcome" as const, outcomeId: outcome.id } };
    });
  }
  // Preserve original guidance (notably the carry finder’s check-fit FAQ) first.
  // Replace only this campaign’s generated IDs when reapplied, keeping enrichment
  // idempotent without discarding unrelated authored sections.
  const generatedIds = new Set([...marketing.resultSections, ...common].map(section => section.id));
  const retained = (form.marketing?.resultSections || []).filter(section => !generatedIds.has(section.id));
  marketing.resultSections = [...structuredClone(retained), ...marketing.resultSections, ...common];
  return FormSchema.parse(next);
}
